css: |
  /* Code first: inline code a tinted chip, blocks rounded. */
  #content :not(pre):not([class^=L])>code{background:var(--ptome-color-tint);color:var(--ptome-color-ink);border-radius:4px;padding:.1em .35em;font-size:.875em}
