  .admonitionblock{--admonition:#3B82F6;--admonition-tint:#EFF6FF}
  .admonitionblock.tip{--admonition:#10B981;--admonition-tint:#ECFDF5}
  .admonitionblock.important{--admonition:#8B5CF6;--admonition-tint:#F5F3FF}
  .admonitionblock.warning{--admonition:#F59E0B;--admonition-tint:#FFFBEB}
  .admonitionblock.caution{--admonition:#EF4444;--admonition-tint:#FEF2F2}
  .admonitionblock>table,.admonitionblock>table>tbody,.admonitionblock>table tr{display:block}
  .admonitionblock>table{background:var(--admonition-tint);border-left:5px solid var(--admonition);border-radius:0 6px 6px 0;padding:.75em 1em}
  .admonitionblock>table td{display:block;border:0;padding:0}
  .admonitionblock>table td.content{border-left:0;padding:0;color:inherit}
  .admonitionblock>table td.icon{text-align:left;width:auto;white-space:nowrap;margin-bottom:.35em}
  .admonitionblock td.icon .title{font-size:.8em;text-transform:uppercase;letter-spacing:.06em;color:var(--admonition)}
  .admonitionblock td.icon .title::before{display:inline-flex;align-items:center;justify-content:center;width:1.35em;height:1.35em;margin-right:.5em;border-radius:50%;background:var(--admonition);color:#fff;font-weight:700;letter-spacing:0;vertical-align:-.2em}
  .admonitionblock.note td.icon .title::before{content:"i";font-family:Georgia,serif;font-style:italic}
  .admonitionblock.tip td.icon .title::before{content:"+"}
  .admonitionblock.important td.icon .title::before{content:"!"}
  .admonitionblock.warning td.icon .title::before{content:"!"}
  .admonitionblock.caution td.icon .title::before{content:"\00D7"}
