  @media screen and (min-width:64em){
    body.toc2,body:has(#toc){padding-left:17rem;padding-right:2rem}
    #toc.toc,#toc.toc2{position:fixed;top:0;left:0;bottom:0;width:15rem;margin:0;padding:1.5rem 1rem;overflow:auto;border:0;border-right:1px solid var(--ptome-color-rule);background:var(--ptome-color-tint);font-size:.9em}
    #header>#toc.toc{border-top:0;border-bottom:0}
