    #toc ul ul{padding-left:1em}
  }
  #toc a{color:var(--ptome-color-ink-soft)}
  #toc a:hover{color:var(--ptome-color-link)}
  /* A dark mode, when the reader's system asks for one. */
  @media screen and (prefers-color-scheme:dark){
    :root{--ptome-color-ink:#E5E7EB;--ptome-color-ink-strong:#F9FAFB;--ptome-color-ink-soft:#C0C6CF;--ptome-color-muted:#9CA3AF;--ptome-color-link:#7AA7FF;--ptome-color-tint:#1F2430;--ptome-color-rule:#2E3440;--ptome-color-rule-soft:#3B4252;color-scheme:dark}
    html,body{background:#12151C;color:var(--ptome-color-ink)}
    #header,#content,#footnotes,#footer{color:var(--ptome-color-ink)}
    #footer{background:#0C0F14}
    #footer-text{color:var(--ptome-color-muted)}
    h1,h2,h3,h4,h5,h6,#toctitle,.sidebarblock>.content>.title{color:var(--ptome-color-ink-strong)}
    p,li,dd,dt,td,th,blockquote,.paragraph.lead>p,#preamble>.sectionbody>[class=paragraph]:first-of-type p{color:var(--ptome-color-ink)}
    table.tableblock>thead>tr>th,table.tableblock>tfoot>tr>*,table.tableblock th{color:var(--ptome-color-ink-strong)}
    .listingblock>.content>pre,.literalblock pre,.sidebarblock,.exampleblock>.content{background:var(--ptome-color-tint);color:var(--ptome-color-ink)}
    table.tableblock{background:transparent}
    .exampleblock>.content,.sidebarblock{border-color:var(--ptome-color-rule)}
    table.tableblock,th.tableblock,td.tableblock{border-color:var(--ptome-color-rule)}
    .admonitionblock{--admonition-tint:#1A2333}
    .admonitionblock.tip{--admonition-tint:#13261F}
    .admonitionblock.important{--admonition-tint:#221B33}
    .admonitionblock.warning{--admonition-tint:#2A2212}
    .admonitionblock.caution{--admonition-tint:#2C1718}
    .title,.quoteblock .attribution,.verseblock .attribution{color:var(--ptome-color-muted)}
    #toc.toc,#toc.toc2{background:#171B24}
    mark{background:#5B4A00;color:inherit}
  }
