css: |
  #content .paragraph p{text-indent:1em;margin:0}
  #content .agency p,#content .docket p,#content .fr-title p{font-family:"Noto Sans",Helvetica,Arial,sans-serif;font-weight:bold;text-indent:0}
  #content .dlist dt{font-family:"Noto Sans",Helvetica,Arial,sans-serif;font-weight:bold;font-size:.83em;text-transform:uppercase}
  #content .billing-code p{font-family:"Noto Sans",Helvetica,Arial,sans-serif;font-weight:bold;font-size:.67em;text-indent:0}
  #content hr{border-top:2px solid #000}
''',
  'magazine-1950s':
      r'''# The 1950s fashion magazine (Brodovitch's *Harper's Bazaar*, Henry
# Wolf's *Esquire*): a hairline Didone in white space, huge black
# initials, photographs floating on white; Bauer Bodoni for the text.
# Stand-ins: Bodoni Moda for Didot, Libre Bodoni for Bauer Bodoni.
#
# In print: the large page of the fashion monthlies (about 10 × 13 in),
# wide margins, two columns two picas apart, ragged text 10 on 14 pt,
# the head centred, a five-line initial.
extends: magazine
tokens:
  font:
    text: { family: Libre Bodoni }
    display: { family: { print: Bodoni Moda 28pt, screen: [Bodoni Moda, serif] }, weight: normal }
    utility: { family: { print: Libre Bodoni, screen: [Libre Bodoni, serif] } }
  size: { text: { print: 10pt, screen: 1.0625rem } }
  leading: { print: 1.4, screen: 1.5 }
  align: { print: start }
  page: { size: [10in, 13in], margin: [1in, 1.125in, 1in, 1.125in] }
styles:
  title: { style: normal }
  .kicker: { font: text, weight: normal, tracking: { print: 0.3em } }
webfonts:
  - Bodoni Moda:400,400italic,700
  - Libre Bodoni:400,400italic,700
pdf:
  title_page:
    text_align: center
    inline_margin_bottom: 30
    title: { font_size: 56, line_height: 1, margin_bottom: 14 }
    subtitle: { font_size: 15 }
  role: { dropcap: { drop_lines: 5 } }
  page_columns: 2
  page_column_gap: 24
  heading: { h2: { font_style: normal, font_size: 15 } }
  quote: { role: { pullquote: { font_style: normal, font_size: 18, border_width: [0.5, 0, 0.5, 0] } } }
css: |
  :root{--mag-head-align:center;--mag-display-style:normal;--mag-kicker-tracking:.3em;--mag-dropcap-lines:5;--mag-text-align:start;--mag-gutter:2.5rem;--mag-body-span:6}
  #content,#footnotes,#footer{grid-column:4/span var(--mag-body-span)}
  #header>h1,#header>.title-page-title{font-weight:400;letter-spacing:-.01em}
''',
  'magazine-1960s':
      r'''# The 1960s Swiss magazine (Fleckhaus's *Twen*, Vignelli's canon): a
# 12-unit grid combined into 2, 3, 4 or 6 columns, gutters one line of
# type, at most two sizes (heads about twice the text), flush left, a
# grotesque, type hung from 2 pt and ½ pt rules. Stand-in: Inter (its
# 18 pt text cut in print).
#
# In print: *Twen*'s large page (about 265 × 335 mm), the grid's three
# columns a line apart, text 9 on 12 pt flush left, heads hung from a
# 2 pt rule, no initial.
extends: magazine
tokens:
  font:
    text: { family: { print: Inter 18pt, screen: Inter } }
    display: { family: { print: Inter 18pt, screen: Inter }, weight: bold }
    utility: { family: { print: Inter 18pt, screen: Inter } }
  size: { text: { print: 9pt, screen: 1rem } }
  leading: { print: 1.35, screen: 1.5 }
  align: { print: start }
  page: { size: [265mm, 335mm], margin: [20mm, 18mm, 22mm, 18mm] }
  rule:
    major: { print: 2pt, screen: 3px, ebook: 3px }
    minor: { print: 0.5pt, screen: 1px, ebook: 1px }
styles:
  title: { style: normal }
webfonts:
  - Inter:400,400italic,700
pdf:
  title_page:
    title: { font_size: 40, line_height: 1.05 }
    subtitle: { font_size: 18, line_height: 1.2 }
  role: { dropcap: { drop_lines: 0 }, kicker: { text_transform: none, letter_spacing: 0 } }
  page_column_gap: 12.15
  columns_count: 2
  heading:
    h2: { font_style: bold, font_size: 9, border_width: [2, 0, 0, 0], border_color: '1A1A1A', padding: [4, 0, 0, 0] }
  quote:
    role:
      pullquote: { font_family: Inter 18pt, font_style: bold, font_size: 18, line_height: 1.2, border_width: [2, 0, 0.5, 0] }
css: |
  :root{--mag-display-style:normal;--mag-kicker-case:none;--mag-kicker-tracking:0;--mag-dropcap-lines:0;--mag-text-align:start;--mag-gutter:1.5em;--mag-end-mark:"";--mag-section-columns:2;--mag-column-min:16rem}
  #header{border-top:var(--ptome-rule-major) solid;padding-top:.5rem}
  #header>h1,#header>.title-page-title{font-size:clamp(2rem,4vw,3rem);letter-spacing:-.02em}
  #header>.dek,.paragraph.dek p{font-size:1.5rem}
  h2,h3{border-top:var(--ptome-rule-minor) solid;padding-top:.4rem;font-size:1.5rem}
  .paragraph.dropcap p::first-letter{initial-letter:normal;-webkit-initial-letter:normal;float:none;font-size:inherit;margin:0;color:inherit;font-family:inherit}
  .quoteblock.pullquote{border-block:0;border-top:var(--ptome-rule-major) solid}
''',
  'magazine-1970s':
      r'''# The 1970s rock tabloid (*Rolling Stone*): an Oxford-rule frame (a
# thick rule and a thin one), slab display type, serif text in three
# columns where columns are wanted, display-italic pull quotes. Stand-in:
# Zilla Slab for the slab.
#
# In print: the tabloid page (about 11 × 14½ in) in an Oxford-rule frame,
# four columns, slab heads, red italic pull quotes between thick and thin
# rules.
extends: magazine
tokens:
  font:
    display: { family: { print: Zilla Slab, screen: [Zilla Slab, serif] }, weight: bold }
    utility: { family: { print: Zilla Slab, screen: [Zilla Slab, serif] } }
  color: { accent: '#B3261E' }
  page: { size: [11in, 14.5in], margin: [0.75in, 0.6in, 0.8in, 0.6in] }
styles:
  title: { style: normal }
webfonts:
  - Zilla Slab:400,400italic,700,700italic
pdf:
  title_page:
    title: { font_size: 48, line_height: 1 }
    subtitle: { font_size: 16 }
  page_columns: 4
  page_frame: { width: [4, 1], gap: 3, offset: 14, color: '1A1A1A' }
  heading: { h2: { font_style: bold } }
  quote:
    role:
      pullquote: { font_family: Zilla Slab, font_style: bold_italic, font_size: 17, font_color: 'B3261E', border_width: [3, 0, 1, 0], border_color: 'B3261E' }
css: |
  :root{--mag-frame-width:6px;--mag-frame-gap:4px;--mag-display-style:normal;--mag-kicker-tracking:.08em}
  body{margin:1rem;min-height:calc(100vh - 2rem)}
  .quoteblock.pullquote blockquote,.quoteblock.pullquote blockquote p{font-style:italic;color:var(--ptome-color-accent)}
''',
  'magazine-1980s':
      r'''# The 1980s technical monthly (*BYTE*, *Creative Computing*): Univers,
# three justified columns, tinted editor's-note sidebars, numbered
# monospace listings, a dinkus between short items. Stand-ins: Archivo
# for Univers, IBM Plex Mono for the listings.
#
# In print: the standard page, three justified columns with hairlines
# between them, text 9 on 11 pt, tinted sidebars, the pull quote in the
# accent blue.
extends: magazine
tokens:
  font:
    text: { family: Archivo }
    display: { family: Archivo, weight: bold }
    utility: { family: Archivo }
    code: { family: IBM Plex Mono }
  size: { text: { print: 9pt, screen: 1rem } }
  leading: { print: 1.22, screen: 1.5 }
  color: { accent: '#0B5C8E', tint: '#E8EEF4' }
styles:
  title: { style: normal }
  sidebar: { background: tint, border: none }
  code-block: { background: none, border: { width: minor, color: ink } }
webfonts:
  - Archivo:400,400italic,700
  - IBM Plex Mono:400,700
pdf:
  title_page:
    title: { font_size: 34, line_height: 1.05 }
    subtitle: { font_size: 13 }
  role: { dropcap: { drop_lines: 2 } }
  page_column_rule_width: 0.25
  page_column_rule_color: '555555'
  heading: { h2: { font_style: bold, font_size: 11 } }
  quote:
    role:
      pullquote: { font_family: Archivo, font_style: bold, font_size: 13, font_color: '0B5C8E', border_color: '0B5C8E' }
css: |
  :root{--mag-display-style:normal;--mag-section-columns:3;--mag-column-min:12rem;--mag-end-mark:"\2022\2009\2022\2009\2022\2009\2022"}
  .sidebarblock{border:0;padding:1rem}
  hr{border:0;text-align:center;height:auto}
  hr::after{content:"\2022\2003\2022\2003\2022\2003\2022"}
''',
  'magazine':
      r'''# The print magazine, for the web (EPIC-kzdb6h; doc/magazine.md): the
# base of the era looks (magazine-1955, ...). Its parts are roles
# (kicker, hed, dek, byline, dateline, lede, dropcap, pullquote,
# caption-lead, credit, end), named after IPTC NITF and Apple News
# Format's roles; its device rules (the `css:` below) never change
# between eras, which set its tokens and the `--mag-*` knobs:
#
# --mag-grid-units, --mag-gutter, --mag-body-span: the page's grid
# --mag-head-align, --mag-display-style: the head's alignment, style
# --mag-kicker-case, --mag-kicker-tracking: the kicker's capitals
# --mag-dropcap-lines: the initial's depth, in lines
# --mag-frame-width, --mag-frame-gap: a thick-and-thin frame (0: none)
# --mag-end-mark: the end of a piece
# --mag-section-columns, --mag-column-min: [.columns] sections
# --mag-text-align: the text's alignment
#
# Its look follows the mid-century general magazine (the 1955 *Look*,
# the 1957 *Scientific American*): a letterspaced capital kicker, an
# italic Didone head, a dek in large text type, three justified columns
# in bounded sections, bold small-capital caption lead-ins. The faces'
# free stand-ins (from Google Fonts; `ptome doctor --look magazine`
# installs them for print): Bodoni Moda (its 28 pt cut in print), Libre
# Caslon Text, Libre Franklin.
#
# In print (doc/magazine.md): the American standard magazine page
# (8⅜ × 10⅞ in), three columns a pica apart, text 9½ on 12½ pt, the
# head, dek and byline across the columns at the top of the piece.
tokens:
  font:
    text: { family: Libre Caslon Text }
    display: { family: { print: Bodoni Moda 28pt, screen: [Bodoni Moda, serif] }, weight: bold }
    utility: { family: Libre Franklin }
  size:
    text: { print: 9.5pt, screen: 1.0625rem }
    headings: { print: [36pt, 12pt, 10.5pt, 9.5pt, 9.5pt, 9.5pt] }
  leading: { print: 1.32, screen: 1.5 }
  page: { size: [8.375in, 10.875in], margin: [0.625in, 0.5in, 0.75in, 0.5in] }
  align: { print: justify }
  hyphenate: true
  color:
    ink: '#1A1A1A'
    accent: '#1A1A1A'
    muted: '#555555'
  rule:
    major: { print: 1.5pt, screen: 2px, ebook: 2px }
    minor: { print: 0.5pt, screen: 1px, ebook: 1px }
styles:
  heading: { font: display, color: ink }
  title: { font: display, style: italic, color: ink }
  caption: { font: utility, size: 0.85, color: muted }
  .kicker: { font: utility, weight: 600, color: accent, tracking: { print: 0.14em } }
  .dek: { font: text, size: 1.3 }
  .byline: { font: utility, size: 0.85 }
  .credit: { font: utility, size: 0.8, color: muted }
templates:
  title-page:
    recto:
      - { attribute: kicker, style: .kicker }
      - title
      - { slot: subtitle, style: .dek }
      - { slot: authors, before: 'By ', separator: ' and ', style: .byline }
      - { attribute: credit, style: .credit }
      - { attribute: issue, style: .credit }
  # A website of pieces (multipage_html5): the link on is a jump line,
  # and each page has a folio.
  multipage-nav-previous: '&#8592; {{title}}'
  multipage-nav-next: 'Continued in {{title}} &#8594;'
  multipage-nav-folio: '{{doctitle}}{{#attr-issue}} · {{attr-issue}}{{/attr-issue}} · {{page}}'
webfonts:
  - Bodoni Moda:400,400italic,700,700italic
  - Libre Caslon Text:400,400italic,700
  - Libre Franklin:400,600,700
# Print: the piece's head across the top of its first page, then its
# columns; the initial, the pull quote across its column between rules,
# the folio at the foot.
pdf:
  # Capitals and small capitals letterspaced (microtype's 0.05 em).
  caps_letter_spacing: 0.05em
  title_page_inline: true
  title_page:
    text_align: left
    inline_margin_bottom: 18
    title: { font_size: 36, line_height: 1.02, margin_top: 4, margin_bottom: 8 }
    subtitle: { font_style: normal, font_size: 14, line_height: 1.22, margin_bottom: 10 }
    authors: { margin_bottom: 2 }
  role:
    kicker: { font_size: 7.5, text_transform: uppercase }
    byline: { font_size: 8 }
    credit: { font_size: 7 }
    dropcap: { drop_lines: 3 }
    dateline: { font_style: bold }
    jump: { font_style: italic }
  link: { font_color: '1A1A1A' }
  page_columns: 3
  page_columns_balance: true
  page_column_gap: 12
  columns_count: 3
  heading:
    margin_top: 10
    margin_bottom: 4
    min_height_after: auto
    h2: { font_style: bold_italic }
  quote:
    role:
      pullquote:
        font_family: Bodoni Moda 28pt
        font_style: italic
        font_size: 15
        line_height: 1.15
        border_left_width: 0
        border_width: [1.5, 0, 1.5, 0]
        border_color: '1A1A1A'
        padding: [8, 0, 8, 0]
  image:
    caption: { font_size: 7.5 }
  footer:
    font_family: Libre Franklin
    font_size: 7
    border_width: 0
    recto: { left: { content: '{issue}' }, right: { content: '{page-number}' } }
    verso: { left: { content: '{page-number}' }, right: { content: '{issue}' } }
css: |
  :root{--mag-grid-units:12;--mag-gutter:1.5rem;--mag-body-span:8;--mag-head-align:start;--mag-display-style:italic;--mag-kicker-case:uppercase;--mag-kicker-tracking:.14em;--mag-dropcap-lines:3;--mag-frame-width:0px;--mag-frame-gap:0px;--mag-end-mark:"\25A0";--mag-section-columns:3;--mag-column-min:14rem;--mag-text-align:justify}
  body{display:grid;grid-template-columns:repeat(var(--mag-grid-units),minmax(0,1fr));column-gap:var(--mag-gutter);align-content:start;margin:0;padding:3rem var(--mag-gutter);min-height:100vh;box-sizing:border-box;border:var(--mag-frame-width) solid currentColor;outline:calc(var(--mag-frame-width)/4) solid currentColor;outline-offset:calc(-1*(var(--mag-frame-width) + var(--mag-frame-gap)))}
  #header,#content,#footnotes,#footer{max-width:none;margin:0;padding-left:0;padding-right:0}
  #header{grid-column:2/-2;text-align:var(--mag-head-align);margin-bottom:2rem}
  #header>h1,#header>.title-page-title{font-style:var(--mag-display-style);font-size:clamp(2.25rem,6vw,4.5rem);line-height:1.05;margin:.25em 0;text-wrap:balance;border:0}
  #header>.kicker{font-size:.8rem;text-transform:var(--mag-kicker-case);letter-spacing:var(--mag-kicker-tracking)}
  #header>.dek{font-size:1.35rem;line-height:1.3;margin:.5em 0 1em;text-wrap:balance}
  #header>.details{display:block;border:0;padding:0;margin:.25em 0;color:inherit;line-height:1.4}
  #header>.details span{margin:0}
  #header>.details br{display:none}
  #content,#footnotes{grid-column:3/span var(--mag-body-span);container-type:inline-size}
  #footer{grid-column:3/span var(--mag-body-span);background:none;border-top:var(--ptome-rule-minor) solid;margin-top:2rem;padding:.75rem 0}
  #footer-text{color:var(--ptome-color-muted);font-family:var(--ptome-font-utility);font-size:.8rem}
  #content p{text-align:var(--mag-text-align);hyphens:auto;-webkit-hyphens:auto;hyphenate-limit-chars:6 2 3;text-wrap:pretty}
  .paragraph.dek p{font-size:1.35rem;line-height:1.3;text-align:var(--mag-head-align);text-wrap:balance}
  .dateline,.caption-lead{font-variant-caps:small-caps;font-weight:700;letter-spacing:.04em}
  .paragraph.dropcap p::first-letter{-webkit-initial-letter:var(--mag-dropcap-lines);initial-letter:var(--mag-dropcap-lines);font-family:var(--ptome-font-display);color:var(--ptome-color-accent);margin-inline-end:.08em}
  @supports not ((initial-letter:1) or (-webkit-initial-letter:1)){.paragraph.dropcap p::first-letter{float:left;font-size:calc(var(--mag-dropcap-lines)*1.4em);line-height:.85;margin-top:.05em}}
  .imageblock.right,.imageblock.left{width:50%;margin-bottom:1rem;shape-outside:margin-box}
  .imageblock.right{float:right;margin-inline-start:var(--mag-gutter)}
  .imageblock.left{float:left;margin-inline-end:var(--mag-gutter)}
  .imageblock.right img,.imageblock.left img{width:100%;height:auto}
  .imageblock>.title{font-style:normal;margin-top:.4em}
  .quoteblock.pullquote{float:right;width:45%;margin:0 0 1rem var(--mag-gutter);padding:.5rem 0;border:0;border-block:var(--ptome-rule-major) solid}
  .quoteblock.pullquote blockquote{padding:0;border:0}
  .quoteblock.pullquote blockquote,.quoteblock.pullquote blockquote p{font-family:var(--ptome-font-display);font-style:var(--mag-display-style);font-size:1.6rem;line-height:1.2;color:inherit;text-align:start;hanging-punctuation:first last}
  .quoteblock.pullquote blockquote::before{content:none}
  .columns{clear:both}
  .sect1.columns>.sectionbody,:is(.sect2,.sect3,.sect4).columns{columns:var(--mag-section-columns) var(--mag-column-min);column-gap:var(--mag-gutter);column-rule:var(--ptome-rule-minor) solid}
  .sect1.columns>.sectionbody :is(h3,.imageblock),:is(.sect2,.sect3,.sect4).columns>:is(h3,h4,h5,.imageblock){column-span:all}
  .paragraph.end p::after,#content>.sect1:last-child>.sectionbody>.paragraph:last-child p::after,#content>.paragraph:last-child p::after{content:"\00a0" var(--mag-end-mark);color:var(--ptome-color-accent)}
  .sidebarblock{border:0;border-block:var(--ptome-rule-minor) solid;border-radius:0}
  .multipage-nav{grid-column:3/span var(--mag-body-span);display:flex;justify-content:space-between;align-items:baseline;gap:1rem;margin:1rem 0;padding:.4rem 0;font-family:var(--ptome-font-utility);font-size:.8rem;border-block:var(--ptome-rule-minor) solid}
  .multipage-nav a{color:inherit;text-decoration:none}
  .multipage-nav a.next{font-style:italic;margin-left:auto}
  .multipage-nav .folio{color:var(--ptome-color-muted);letter-spacing:.06em;text-transform:uppercase;font-size:.7rem}
  @media (max-width:44rem){#header,#content,#footnotes,#footer,.multipage-nav{grid-column:1/-1}}
  @container (max-width:34rem){.imageblock.right,.imageblock.left,.quoteblock.pullquote{float:none;width:auto;margin-inline:0;shape-outside:none}.sect1.columns>.sectionbody,:is(.sect2,.sect3,.sect4).columns{columns:auto}}
  @media print{body{display:block;border:0;outline:0;padding:0}}
''',
  'pleading':
      r'''# A pleading for a California trial court, by the California Rules of
# Court, rules 2.100–2.119: Letter paper; the text 12 point (rule 2.104),
# double-spaced (rule 2.108(1)), on 28 numbered lines a page, three to
# the inch and more (rule 2.108(4): here 24 pt apart), numbered from 1 on
# each page at the left margin, a double line between the numbers and
# the text (rule 2.108(4)); the left margin an inch and more, the right
# half an inch and more (rule 2.107); the page number at the foot and
# the paper's title under it (rule 2.110). On the first page (rule 2.111)
# the attorney's name, address and bar number from line 1, and the
# court's title (`[.court]`) on line 8; the case's title, its number and
# the paper's nature below. The document turns the numbers on
# (`:line-numbers: grid`).
#
# Set in TeX Gyre Termes, a Times (`ptome doctor --look pleading`).
tokens:
  font:
    text: { family: { print: TeX Gyre Termes, screen: [Times New Roman, Times, serif] } }
    display: { family: { print: TeX Gyre Termes, screen: [Times New Roman, Times, serif] }, weight: bold }
  size:
    text: { print: 12pt, screen: 17px }
    headings: { print: [12pt, 12pt, 12pt, 12pt, 12pt, 12pt] }
  leading: { print: 2, screen: 1.6 }
  measure: { screen: 36em }
  paragraph: { signal: indent, indent: { print: 0.5in } }
  align: { print: start }
  hyphenate: { print: false }
  color: { ink: '#000000', link: '#000000' }
  rule: { hairline: { print: 0.5pt, screen: 1px, ebook: 1px } }
  # 28 lines 24 pt apart from an inch down; the text an inch and a half
  # in, the numbers in the margin beside it.
  page: { size: Letter, margin: [1in, 0.5in, 0.6667in, 1.5in] }
styles:
  heading: { font: display, color: ink, space-before: { print: 0pt }, space-after: { print: 0pt }, keep-with-next: true }
  title: { font: display, color: ink }
  link: { color: ink }
pdf:
  page_baseline_grid: 24
  # (Double spacing at 24 pt whatever the face: the grid's step.)
  base_line_pitch: 24
  heading:
    text_align: center
  line_numbers:
    side: left
    interval: 1
    restart: page
    grid_pitch: 24
    font_size: 12
    gap: 0.3in
    rule: double
    rule_width: 0.5
  role:
    court: { grid_line: 8, text_align: center, font_style: bold }
    # (The first paragraph, the attorney's, at the body's size.)
    lead: { font_size: 12 }
  header:
    recto: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
    verso: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
  footer:
    height: 0.6in
    font_size: 10
    border_width: 0.5
    recto: { left: { content: '' }, center: { content: "{page-number} +\n{document-title}" }, right: { content: '' } }
    verso: { left: { content: '' }, center: { content: "{page-number} +\n{document-title}" }, right: { content: '' } }
''',
  'ptome': r'''# Ptome's house look (ADR-0011, ADR-0023; doc/style.md): Asciidoctor's,
# asciidoctor-pdf's and asciidoctor-epub3's looks, changed as the rules of
# typesetting ask: in print, a measure of about 75 characters, more open
# lines, headings in the sans, code in a tint, tables with rows only; on
# screen, a 42em measure and near-black headings; in an e-book, the
# reader's body text, hyphenated. A value by medium (`print`: the PDF;
# `screen`: HTML; `ebook`: EPUB) applies there alone; a plain one applies
# everywhere. A look that changes this one starts with `extends: ptome`.
tokens:
  font:
    text: { family: { print: Noto Serif } }
    display:
      family: { print: Noto Sans }
      weight: { print: bold, screen: 600 }
    code: { family: { print: M+ 1mn }, size: { print: 0.9 } }
  size:
    # 10–12 pt in print (Practical Typography).
    text: { print: 10.5pt }
    headings: { print: [26pt, 20pt, 14pt, 12pt, 11pt, 10.5pt] }
  # 120–145% in print: open for a serif with a large x-height.
  leading: { print: 1.4 }
  # About 80 characters on screen (75 zeros of the text face: the old
  # 42em, kept as the face changes); print takes its measure from the
  # page.
  measure: { screen: 75ch }
  paragraph: { signal: { print: space }, space: { print: 6pt } }
  # An e-book's reading system owns the body text (ADR-0023 decision 2):
  # no size, line spacing or alignment for `ebook`; hyphenated.
  hyphenate: { ebook: true }
  color:
    ink: { print: '#1F1F1F' }
    ink-strong: '#191919'
    ink-soft: '#444444'
    muted: '#555555'
    link: '#2156A5'
    tint: '#F7F7F8'
    rule: '#DDDDDD'
    rule-soft: '#CCCCCC'
  rule:
    hairline: { print: 0.5pt, screen: 1px }
    heavy: { print: 1pt, screen: 1px }
  page:
    # About 75 characters of 10.5pt Noto Serif on A4 or Letter.
    margin: [0.75in, 1.5in, 0.875in, 1.5in]
    inner: 1.75in
    outer: 1.25in
styles:
  link: { color: link }
  heading:
    font: display
    color: ink-strong
    space-before: { print: 16pt }
    space-after: { print: 6pt }
    leading: { print: 1.2 }
    keep-with-next: { print: true }
  title: { color: ink-strong }
  subtitle: { color: { print: ink-soft } }
  caption:
    font: { print: display }
    weight: { print: normal }
    size: { print: 9.5pt }
    color: { print: muted }
  code-block:
    size: { print: 9.5pt }
    color: { print: ink }
    background: { print: tint }
    border: { print: none, screen: none }
    radius: { print: 2pt }
    padding: { print: 9pt }
    leading: { print: 1.35 }
  code: { color: { print: ink } }
  sidebar: { background: { print: tint }, border: { print: none } }
  sidebar-title: { font: { print: display }, color: { print: ink-strong } }
  admonition:
    rule: { print: { width: 2pt, color: rule-soft } }
  admonition-label:
    font: { print: display }
    weight: { print: bold }
    color: { print: ink-soft }
  table:
    frame: { print: { width: heavy, color: ink-strong }, screen: { width: heavy } }
    frame-sides: { print: none, screen: none }
    rows: { print: { width: hairline, color: rule }, screen: { width: hairline } }
    columns: { print: none, screen: none }
    head-rule:
      print: { width: heavy, color: ink-strong }
      screen: { width: heavy, color: ink-strong }
    stripes: { print: none }
  table-head: { font: { print: display }, background: { print: none } }
  .small-caps: { variant: small-caps }
# What tokens can't say, in the PDF theme's own keys: the files of the
# sans asciidoctor-pdf bundles.
pdf:
  font:
    catalog:
      merge: true
      Noto Sans:
        normal: GEM_FONTS_DIR/notosans-regular-subset.ttf
        bold: GEM_FONTS_DIR/notosans-bold-subset.ttf
        italic: GEM_FONTS_DIR/notosans-italic-subset.ttf
        bold_italic: GEM_FONTS_DIR/notosans-bold_italic-subset.ttf
# Print-grade prose on screen, where the browser can (progressive
# enhancement: one that lacks a property ignores it, and the text reads as
# before): words hyphenated in the document's language (`lang`; not when
# the document unsets `hyphens`, its body then `nohyphens`), the
# paragraph's last lines balanced against a short last line (text-wrap:
# pretty), old-style figures, punctuation hung at the ends (Safari), and
# headings' lines balanced.
css: |
  #content .paragraph>p,#content li>p,#content dd>p,#content .quoteblock blockquote p,#content .admonitionblock td.content>.paragraph>p{-webkit-hyphens:auto;hyphens:auto;text-wrap:pretty;font-variant-numeric:oldstyle-nums proportional-nums;hanging-punctuation:first allow-end last}
  h1,h2,h3,h4,h5,h6,#toctitle,.sidebarblock>.content>.title{text-wrap:balance}
  .nohyphens #content p,.nohyphens #content li,.nohyphens #content dd{-webkit-hyphens:manual;hyphens:manual}
''',
  'readers-bible':
      r'''# A reader's edition of the Bible from a document in units (`:units:
# bible, kjv`), the text as a book's: one column, no verse numbers, no
# cross-references (the translators' notes stay at the foot); each
# chapter's number in the margin beside its first line, as a reader's
# edition such as the ESV Reader's sets it; the running head the page's
# first and last verse, to find a passage by.
# A 5½ × 8½ in page, the text 11 on 14.
#
# Set in Crimson Pro (`ptome doctor --look readers-bible`).
extends: reference-bible
tokens:
  size:
    text: { print: 11pt, screen: 19px }
    headings: { print: [20pt, 11pt, 11pt, 11pt, 11pt, 11pt] }
  leading: { print: 1.27, screen: 1.6 }
  page: { size: [5.5in, 8.5in], margin: [0.7in, 0.7in, 0.75in, 0.75in], grid: true }
pdf:
  page:
    columns: 1
  heading:
    # (The chapter's number in the margin, not dropped into the text.)
    h3_drop_lines: 0
    h3_display: margin
    h3_margin_content: '{{attr-number}}'
    h3_margin_font_size: 18
    h3_margin_font_style: bold
    h3_margin_skip_roles: [parallel, psalm-title]
  units:
    verse:
      label_display: none
  role:
    xref: { display: none }
    xref-mark: { display: none }
''',
  'reference-bible': r'''# A reference Bible from a document in units (`:units: bible, kjv`): two
# justified columns with the cross-references in a column between them
# (the scheme's `x` stream, entries in the role `xref`); each chapter's
# number dropped two lines into its first verse, no heading over it;
# light verse numbers; the running head the page's first and last verse
# (`Genesis 2:20–3:7`); the lines matched on a baseline grid, so that on
# thin paper the show-through falls between them; the translators' notes
# at the foot. A personal size, 5½ × 8¼ in, the text 9 on 11 (settings
# after PTXprint's reference-Bible defaults, not measured from a book).
#
# Options over it, in a theme that `extends: look`: red letter,
# `role: { wj: { font_color: A01818 } }`. A chapter's first verse goes
# without its number when the scheme says (`{{^first}}…{{/first}}` in the
# verse's `label`).
#
# Set in Crimson Pro (`ptome doctor --look reference-bible`).
tokens:
  font:
    text: { family: { print: Crimson Pro, screen: [Crimson Pro, Georgia, serif] } }
    display: { family: { print: Crimson Pro, screen: [Crimson Pro, Georgia, serif] }, weight: bold }
  size:
    text: { print: 9pt, screen: 18px }
    headings: { print: [16pt, 9pt, 9pt, 9pt, 9pt, 9pt] }
  leading: { print: 1.22, screen: 1.5 }
  measure: { screen: 34em }
  paragraph: { signal: indent, indent: { print: 1em } }
  align: { print: justify }
  hyphenate: { print: true }
  color: { ink: '#000000', link: '#000000' }
  rule: { hairline: { print: 0.4pt, screen: 1px, ebook: 1px } }
  page: { size: [5.5in, 8.25in], margin: [0.55in, 0.45in, 0.55in, 0.45in], grid: true }
styles:
  heading: { font: display, color: ink, space-before: { print: 4pt }, space-after: { print: 2pt }, keep-with-next: true }
  title: { font: display, color: ink }
  link: { color: ink }
pdf:
  page:
    columns: 2
    column_gap: 0.85in
  heading:
    h2: { text_align: center }
    # (A chapter's number dropped into its first verse.)
    h3_drop_lines: 2
    h3_drop_content: '{{attr-number}}'
    h3_drop_font_style: bold
    # (Past a pericope's parallel passages, to its first verse.)
    h3_drop_skip_roles: [parallel, psalm-title]
    h4: { font_style: italic, text_align: center }
    h5: { font_style: italic }
  side_notes:
    column: center
    item_spacing: 2
  role:
    xref: { display: side, font_size: 6.5 }
    # (The divine name in small capitals: the face's, or made from its
    # capitals; not Unicode's small-capital letters, which few faces have.)
    nd: { font_variant: small-caps }
    book-title: { font_style: italic, text_align: center }
    psalm-title: { font_style: italic }
    poetry: { text_align: left }
  # (Light verse numbers.)
  units:
    verse:
      label_font_color: '707070'
  footnotes:
    font_size: 7
    placement: page
  running_content_units: verse
  header:
    height: 0.45in
    font_size: 8
    recto:
      left: { content: '' }
      center: { content: '{page-units-long}' }
      right: { content: '{page-number}' }
    verso:
      left: { content: '{page-number}' }
      center: { content: '{page-units-long}' }
      right: { content: '' }
  footer:
    recto: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
    verso: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
css: |
  #content .chapter>h3{float:left;font-size:2.6em;line-height:1;margin:0 .15em 0 0}
''',
  'scholarly-monograph':
      r'''# The scholarly monograph: a US university press's 6 × 9 in book, as
# doc/typography.md's measurements set it. Margins from the nine measured
# university-press books (inner 0.79, outer 0.83, head 0.88, foot 1 in);
# the text 10 on 12 (Bringhurst's routine setting and his own), justified
# and hyphenated, paragraphs by a 1 em indent and none after a heading;
# displayed quotations (extracts) and footnotes 9 on 11, the extracts
# indented both sides without rules or quotation marks. A chapter opens
# a recto with its title about 11 pc down, its number above it; sections
# in small capitals, subsections in italic. Running heads in italic, the
# book's title on the verso and the chapter's on the recto, the folios at
# the head's outer corners; none on a chapter's opening page. The index
# in two columns, run on: a term's subterms after semicolons in its own
# paragraph, as Chicago's run-in style sets them.
#
# The face's free stand-in for Minion and Sabon: Crimson Pro (`ptome
# doctor --look scholarly-monograph`).
tokens:
  font:
    text: { family: { print: Crimson Pro, screen: [Crimson Pro, Minion Pro, serif] } }
    display: { family: { print: Crimson Pro, screen: [Crimson Pro, Minion Pro, serif] }, weight: normal }
  size:
    text: { print: 10pt, screen: 19px }
    # The book's title, chapters (a book's level 1), sections, subsections.
    headings: { print: [24pt, 16pt, 10pt, 10pt, 10pt, 10pt] }
  leading: { print: 1.2, screen: 1.55 }
  measure: { screen: 33em }
  paragraph: { signal: indent, indent: { print: 1em } }
  align: { print: justify }
  hyphenate: { print: true }
  color: { ink: '#000000', link: '#000000' }
  rule: { hairline: { print: 0.4pt, screen: 1px, ebook: 1px } }
  page: { size: [6in, 9in], margin: [0.88in, 0.83in, 1in, 0.79in] }
styles:
  heading: { font: display, weight: normal, color: ink, space-before: { print: 18pt }, space-after: { print: 6pt }, keep-with-next: true }
  title: { font: display, weight: normal, color: ink }
  link: { color: ink }
pdf:
  # (10 on 12 whatever the face's own line spacing.)
  base_line_pitch: 12
  page:
    margin_profile: university-press
  heading:
    chapter_break_before: always
    # (The chapter's title about 11 pc below the head margin.)
    h2:
      margin_page_top: 132
      margin_bottom: 36
      line_height: 1.15
    h3: { font_variant: small-caps, margin_top: 18 }
    h4: { font_style: italic, margin_top: 12 }
  caps_letter_spacing: 0.05em
  prose:
    margin_bottom: 0
  # Extracts: 9 on 11, indented both sides, no rule, no quotation marks.
  quote:
    font_size: 9
    line_height: 1.113
    border_left_width: 0
    padding: [0, 15, 0, 15]
    cite:
      font_size: 8.5
      font_color: '000000'
  footnotes:
    font_size: 9
    line_height: 1.113
  index:
    columns: 2
    layout: run-on
    font_size: 9
  title_page:
    text_align: center
  header:
    height: 0.88in
    vertical_align: middle
    font_size: 9
    font_style: italic
    recto:
      left: { content: '' }
      center: { content: '{chapter-title}' }
      right: { content: '{page-number}' }
    verso:
      left: { content: '{page-number}' }
      center: { content: '{document-title}' }
      right: { content: '' }
  footer:
    border_width: 0
    recto: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
    verso: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
webfonts:
  - Crimson Pro:400,400italic,700,700italic
css: |
  #content h2{margin-top:6em}
  #content h3{font-variant:small-caps;letter-spacing:.05em}
  #content h4{font-style:italic}
  .quoteblock{border:none;font-size:.9em;margin-left:1.5em;margin-right:1.5em}
  .quoteblock blockquote::before{content:none}
''',
  'scotus-booklet':
      r'''# A brief in the booklet format of the Supreme Court of the United
# States, by its Rule 33.1: a 6⅛ × 9¼ in page; the text in a Century
# family, 12 point with 2 points or more of leading (12 on 14), the
# footnotes 10 point, also with 2 points (10 on 12); the text field,
# footnotes included, no more than 4⅛ × 7⅛ in, so margins of an inch at
# the sides and 1 1/16 in at the head and foot (at least ¾ in, as the rule
# asks). Headings centred in bold; the page number at the foot.
#
# The cover's colour is the brief's (Rule 33.1(g): a petition white, a
# brief in opposition orange, a petitioner's brief on the merits light
# blue, a respondent's light red, a reply yellow, an amicus green; the
# others tan): a brief sets it over the look, `extends: look` and
# `title_page: { background_color: … }` (doc/looks.md).
#
# The Century family's free stand-in is TeX Gyre Schola, a New Century
# Schoolbook (`ptome doctor --look scotus-booklet`).
tokens:
  font:
    text: { family: { print: TeX Gyre Schola, screen: [Century Schoolbook, New Century Schoolbook, serif] } }
    display: { family: { print: TeX Gyre Schola, screen: [Century Schoolbook, New Century Schoolbook, serif] }, weight: bold }
  size:
    text: { print: 12pt, screen: 18px }
    headings: { print: [14pt, 12pt, 12pt, 12pt, 12pt, 12pt] }
  leading: { print: 1.1667, screen: 1.5 }
  measure: { screen: 34em }
  paragraph: { signal: indent, indent: { print: 2em } }
  align: { print: justify }
  hyphenate: { print: true }
  color: { ink: '#000000', link: '#000000' }
  rule: { hairline: { print: 0.5pt, screen: 1px, ebook: 1px } }
  page: { size: [6.125in, 9.25in], margin: [1.0625in, 1in, 1.0625in, 1in] }
styles:
  heading: { font: display, color: ink, space-before: { print: 12pt }, space-after: { print: 6pt }, keep-with-next: true }
  title: { font: display, color: ink }
  link: { color: ink }
pdf:
  heading:
    text_align: center
  title_page:
    text_align: center
  footnotes:
    font_size: 10
    line_height: 1.2
  header:
    recto: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
