  size:
    text: { print: 10.5pt, screen: 20px }
    # The book's title, chapters (a book's level 1), sections, the rest.
    headings: { print: [30pt, 27pt, 18.9pt, 14pt, 11.5pt, 10.5pt], screen: [2.4em, 2.1em, 1.6em, 1.3em, 1.1em, 1em] }
  leading: { print: 1.2, screen: 1.5 }
  measure: { screen: 34em }
  paragraph: { signal: space, space: { print: 6.3pt } }
  align: { print: justify }
