    muted: '#555555'
  rule: { hairline: { print: 0.5pt, screen: 1px, ebook: 1px } }
  # 30 pc of 7 in: 1 in each side.
  page: { size: [7in, 9.1875in], margin: [0.875in, 1in, 0.875in, 1in] }
styles:
  heading: { font: display, color: ink, space-before: { print: 18pt }, space-after: { print: 6pt }, leading: 1.15, keep-with-next: true }
  title: { font: display, color: ink }
  subtitle: { font: display, weight: normal, color: ink }
  link: { color: link }
  code: { color: ink }
