  sidebar: { background: none, border: { width: hairline, color: ink } }
  sidebar-title: { font: display, color: ink }
  admonition-label: { font: display, color: ink }
  table: { frame: none, rows: { width: hairline, color: ink }, columns: none, head-rule: { width: hairline, color: ink } }
