  # The running foot: the page number outside, then the chapter (verso)
  # or section (recto). No head.
  header:
    recto: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
    verso: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
  # (Its baseline 42.75 pt above the page's foot, 9 point.)
  footer:
    height: 0.875in
    vertical_align: bottom
    padding: [0, 0, 40.4, 0]
    font_size: 9
    font_family: Fira Sans Condensed
    recto:
      left: { content: '' }
      center: { content: '' }
      right: { content: '{section-or-chapter-title} | *{page-number}*' }
    verso:
      left: { content: '*{page-number}* | {chapter-title}' }
      center: { content: '' }
      right: { content: '' }
# The faces on the web, from Google Fonts.
webfonts:
  - Crimson Pro:400,400italic,700,700italic
  - Fira Sans Condensed:400,600
  - Ubuntu Mono:400,400italic,700,700italic
css: |
  .literalblock pre,.listingblock>.content>pre{padding:0 0 0 17pt}
  .admonitionblock>table{border-top:1px solid;border-bottom:1px solid}
  .admonitionblock td.icon .title{text-transform:uppercase}
''',
  'trade-novel':
      r'''# The trade novel: a paperback of fiction in the British B format
# (129 × 198 mm), as doc/typography.md's book-trade tradition sets it.
# An old-style face, 10.25 on 12.25, justified and hyphenated, on a
# baseline grid; paragraphs by a 1 em indent, none after a heading or a
# break; scene breaks as space, an asterism where a page boundary would
