  size:
    text: { print: 10.25pt, screen: 19px }
    # The book's title, chapters (a book's level 1), then scene titles.
    headings: { print: [24pt, 14pt, 10.25pt, 10.25pt, 10.25pt, 10.25pt] }
  leading: { print: 1.195, screen: 1.55 }
  measure: { screen: 31em }
  paragraph: { signal: indent, indent: { print: 1em } }
  align: { print: justify }
  hyphenate: { print: true }
  color: { ink: '#000000', link: '#000000' }
  rule: { hairline: { print: 0.4pt, screen: 1px, ebook: 1px } }
  page: { size: [129mm, 198mm], margin: [16mm, 15mm, 20mm, 17mm], grid: true }
styles:
  heading: { font: display, weight: normal, color: ink, space-before: { print: 12.25pt }, space-after: { print: 12.25pt }, keep-with-next: true }
  title: { font: display, weight: normal, color: ink }
  link: { color: ink }
pdf:
  # (10.25 on 12.25 whatever the face's own line spacing.)
  base_line_pitch: 12.25
  page:
    margin_profile: trade
    margin_whole_lines: true
  heading:
    chapter_break_before: always
    # (A chapter on a recto, sunk a third of the page, its title centred
    # and its first paragraph opened by a two-line initial and three words
    # in small capitals.)
    h2:
      text_align: center
      margin_page_top: 150
      margin_bottom: 24.5
      initial_lines: 2
      initial_lead_in: 3
      initial_gap: 0.15em
  # (Capitals and small capitals letterspaced, as Bringhurst asks.)
